<style>
*{box-sizing:border-box}body{margin:0;background:#f6f7fb;color:#25375d;font:14px/1.5 Arial,sans-serif}
a{color:#274875;text-decoration:none}.wrap{max-width:1120px;margin:0 auto;padding:25px 18px 60px}
.top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px;flex-wrap:wrap}
.top a{border:1px solid #dee4ee;background:#fff;padding:8px 12px;border-radius:8px}
h1{font-size:25px;margin:12px 0 4px;color:#233a68}h2{font-size:17px;color:#233a68;margin:0 0 13px}
p.lead{margin:0 0 20px;color:#73819c}.card{background:#fff;border:1px solid #e2e7f0;border-radius:15px;padding:19px;margin:15px 0;overflow-x:auto}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:12px}.grid .card{margin:0}
.number{font-weight:800;font-size:25px;color:#23416f}.muted{color:#71809a;font-size:12px}
label{display:block;font-weight:bold;color:#32476d;font-size:12px;margin:10px 0 6px}
input,select{width:100%;max-width:340px;padding:10px 12px;border:1px solid #d5ddeb;border-radius:9px;background:#fff;color:#283c65;font:inherit}
button,.btn{background:#273f70;color:#fff;padding:10px 15px;border:none;border-radius:9px;cursor:pointer;font-weight:bold;display:inline-block}
button:hover,.btn:hover{background:#385989;color:#fff}.btn-light{background:#fff;color:#274270;border:1px solid #d7dfeb}
form.inline{display:flex;gap:10px;flex-wrap:wrap;align-items:end}.field{min-width:170px}
.table{width:100%;border-collapse:collapse;min-width:650px}th,td{text-align:left;border-bottom:1px solid #ebedf4;padding:11px 9px;vertical-align:top}th{color:#79869f;font-size:12px;background:#fafbfe}
.msg{border-radius:10px;padding:12px 14px;margin:14px 0}.msg.err{background:#fff0f2;color:#a42b4b}.msg.ok{background:#ecfbf1;color:#246947}
.pill{display:inline-block;padding:3px 9px;border-radius:20px;font-size:11px;font-weight:bold;background:#fff0f5;color:#ae4b77}
@media(max-width:700px){.wrap{padding:15px 12px 50px}.table{font-size:12px}.grid{grid-template-columns:1fr 1fr}input,select{max-width:100%}}
</style>
